-- ADR-0148 §6: record rows, the content-free facts a session keeps about itself (an effective mode change, a released estimate).
-- ADDITIVE and deliberately NOT a table rebuild, for 0021's reasons: session_messages carries the ADR-0104 coverage triggers and its
-- b-tree root page is pinned by the upgrade tests, and a rebuild drops the former and moves the latter. drizzle-kit generates a rebuild
-- for table-level CHECKs, so the same five constraints are written as column constraints, which SQLite accepts on ADD COLUMN and tests
-- against existing rows (all NULL, so they hold). The shape check is attached to the LAST added column, so every column it names exists.
-- A fresh database and an upgraded one both come from this file, so they carry identical constraints.
ALTER TABLE `session_messages` ADD `record_kind` text CONSTRAINT "session_messages_record_kind_check" CHECK ("record_kind" is null or "record_kind" in ('mode_change', 'cost_release'));--> statement-breakpoint
ALTER TABLE `session_messages` ADD `record_from` text CONSTRAINT "session_messages_record_from_check" CHECK ("record_from" is null or "record_from" in ('ask', 'plan', 'accept-edits', 'auto'));--> statement-breakpoint
ALTER TABLE `session_messages` ADD `record_to` text CONSTRAINT "session_messages_record_to_check" CHECK ("record_to" is null or "record_to" in ('ask', 'plan', 'accept-edits', 'auto'));--> statement-breakpoint
ALTER TABLE `session_messages` ADD `record_microcents` integer CONSTRAINT "session_messages_record_microcents_check" CHECK ("record_microcents" is null or (typeof("record_microcents") = 'integer' and "record_microcents" between 0 and 9007199254740991)) CONSTRAINT "session_messages_record_shape_check" CHECK (("record_kind" is null and "record_from" is null and "record_to" is null and "record_microcents" is null) or ("record_kind" is not null and "role" = 'system' and "compaction_dropped_through_sequence" is null and "interruption_reason" is null and "interruption_code" is null and ("content_parts" is null or "content_parts" = '[]') and (("record_kind" = 'mode_change' and "record_from" is not null and "record_to" is not null and "record_from" <> "record_to" and "record_microcents" is null) or ("record_kind" = 'cost_release' and "record_microcents" is not null and "record_from" is null and "record_to" is null))));
